import { FIELD_LABELS } from './labels.js';

const SUMMARY_FIELDS = ['name', 'businessName', 'website', 'industry', 'challenge', 'goal'];

/** Details shown in the handoff summary — only what the visitor shared. */
export function leadSummaryRows(lead = {}) {
  return SUMMARY_FIELDS.filter((key) => lead[key]).map((key) => ({ key, label: FIELD_LABELS[key], value: lead[key] }));
}

/**
 * Preview of the pre-filled WhatsApp message. The authoritative message (and wa.me link) is
 * generated by the server when the visitor continues; this mirrors its format.
 */
export function previewWhatsAppMessage(lead = {}) {
  const rows = leadSummaryRows(lead);
  const lines = ["Hi SEO Virji team! I've just been chatting with your AI consultant and would like to continue the conversation."];
  if (rows.length) lines.push('', ...rows.map((r) => `• ${r.label}: ${r.value}`));
  return lines.join('\n');
}
